description:
Build the seqlock of lesson 3.05 for any trivially copyable state, storing the payload in atomic words so that reading during a write is not undefined behaviour:

```cpp
template <typename T>
class SeqLock
{
public:
    static_assert(std::is_trivially_copyable_v<T>);
    void write(const T& value);
    std::optional<T> tryRead() const;
    T read() const;
    std::uint32_t sequence() const;
};
```

- **write** (one writer only): increment the sequence (now odd), copy the value into the words with relaxed atomic stores, increment the sequence again (now even). Use the fences from the lesson.
- **tryRead** makes one attempt: if the sequence is odd, or changes during the copy, return `std::nullopt`; otherwise the copied value.
- **read** retries `tryRead` until it succeeds.
- **sequence** returns the current counter (twice the number of completed writes when nothing is writing).
- Before the first write, reads return a value-initialised `T`.

starter.solution.cpp:
#include <atomic>
#include <cstdint>
#include <optional>
#include <type_traits>

template <typename T>
class SeqLock
{
public:
    static_assert(std::is_trivially_copyable_v<T>);
    void write(const T& value) { latest = value; }
    std::optional<T> tryRead() const { return std::nullopt; }
    T read() const { return latest; }
    std::uint32_t sequence() const { return 0; }

private:
    T latest{};
};

solution.solution.cpp:
#include <array>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <optional>
#include <type_traits>

template <typename T>
class SeqLock
{
public:
    static_assert(std::is_trivially_copyable_v<T>);

    void write(const T& value)
    {
        const std::uint32_t s{ seq.load(std::memory_order_relaxed) };
        seq.store(s + 1, std::memory_order_relaxed);
        std::atomic_thread_fence(std::memory_order_release);
        std::array<std::uint64_t, WORDS> raw{};
        std::memcpy(raw.data(), &value, sizeof(T));
        for (std::size_t i{ 0 }; i < WORDS; ++i) words[i].store(raw[i], std::memory_order_relaxed);
        seq.store(s + 2, std::memory_order_release);
    }

    std::optional<T> tryRead() const
    {
        const std::uint32_t before{ seq.load(std::memory_order_acquire) };
        if (before & 1) return std::nullopt;
        std::array<std::uint64_t, WORDS> raw{};
        for (std::size_t i{ 0 }; i < WORDS; ++i) raw[i] = words[i].load(std::memory_order_relaxed);
        std::atomic_thread_fence(std::memory_order_acquire);
        if (seq.load(std::memory_order_relaxed) != before) return std::nullopt;
        T value;
        std::memcpy(&value, raw.data(), sizeof(T));
        return value;
    }

    T read() const
    {
        for (;;)
            if (const auto v{ tryRead() }) return *v;
    }

    std::uint32_t sequence() const { return seq.load(std::memory_order_acquire); }

private:
    static constexpr std::size_t WORDS{ (sizeof(T) + 7) / 8 };
    std::atomic<std::uint32_t> seq{ 0 };
    std::array<std::atomic<std::uint64_t>, WORDS> words{};
};

unitTests:
#include <cstring>
#include <thread>
struct Player { float x; float y; std::int32_t health; std::int32_t check; };

TEST("reads see the latest write") {
    SeqLock<Player> lock;
    CHECK_EQ(lock.read().health, 0);
    lock.write({ 1.5f, -2.0f, 87, 0 });
    const Player p{ lock.read() };
    CHECK_EQ(p.x, 1.5f); CHECK_EQ(p.y, -2.0f); CHECK_EQ(p.health, 87);
    CHECK_EQ(lock.sequence(), 2u);
    lock.write({ 0, 0, 50, 0 });
    CHECK_EQ(lock.sequence(), 4u);
    CHECK(lock.tryRead().has_value());
}
TEST("odd-sized states") {
    struct Odd { char name[13]; std::uint8_t level; };
    SeqLock<Odd> lock;
    Odd o{};
    std::memcpy(o.name, "Ada Lovelace", 13);
    o.level = 9;
    lock.write(o);
    CHECK_EQ(std::string(lock.read().name), std::string("Ada Lovelace"));
    CHECK_EQ(lock.read().level, 9);
}
TEST("no torn reads under a real writer") {
    SeqLock<Player> lock;
    std::atomic<bool> stop{ false };
    std::thread writer{ [&] {
        for (std::int32_t i{ 1 }; !stop.load(); ++i)
            lock.write({ static_cast<float>(i), static_cast<float>(i) * 2, i, -i });
    } };
    bool consistent{ true };
    for (int k{ 0 }; k < 200000; ++k)
    {
        const Player p{ lock.read() };
        if (p.check != -p.health || p.y != p.x * 2) consistent = false;
    }
    stop = true;
    writer.join();
    CHECK(consistent);
}

